import React from 'react';

const styles = {
  header: {
    backgroundColor: '#004d40', // A deep, professional green
    color: 'white',
    padding: '24px',
    borderBottom: '4px solid #00796b',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  titleContainer: {
    // This container groups the title and subtitle
  },
  title: {
    fontSize: '2.5rem',
    fontWeight: 'bold',
    margin: 0,
  },
  subtitle: {
    fontSize: '1.25rem',
    marginTop: '4px',
    fontStyle: 'italic',
  },
  nav: {
    // No margin needed now as flexbox handles alignment
  },
  navLink: {
    color: 'white',
    textDecoration: 'none',
    marginLeft: '24px', // Use marginLeft for spacing between links
    fontSize: '1.1rem',
  },
};

const Header = () => {
  return (
    <header style={styles.header}>
      <div style={styles.container}>
        <div style={styles.titleContainer}>
          <h1 style={styles.title}>Dietitian Pradeepa's Clinic</h1>
          <p style={styles.subtitle}></p>
        </div>
        <nav style={styles.nav}>
          <a href="#home" style={styles.navLink}>Home</a>
          <a href="#about" style={styles.navLink}>About Us</a>
          <a href="#services" style={styles.navLink}>Services</a>
          <a href="#contact" style={styles.navLink}>Contact Us</a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
